package com.medicore.notification.controller; import com.medicore.notification.dto.*; import com.medicore.notification.service.NotificationService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService service; public NotificationController(NotificationService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public NotificationResponse create(@Valid @RequestBody NotificationRequest r){return service.create(r);} @GetMapping("/{id}") public NotificationResponse find(@PathVariable Long id){return service.find(id);} @PatchMapping("/{id}/status") public NotificationResponse status(@PathVariable Long id,@RequestParam String value){return service.status(id,value);}}
